/* Quick-fire options and explanations are plain text where a pair of backticks shows code. */
(()=>{
'use strict';
const RQ=globalThis.RQ=globalThis.RQ||{};

/* [xp, title]. The top title is the XP of every mission in the course, so it is reachable only by finishing it; a test keeps
   it at or below that total. */
RQ.RANKS=[[0,'Tide-Pool Newcomer'],[60,'Let Binder'],[300,'Borrow Tamer'],[900,'Lifetime Keeper'],[1090,'Borrow Checker Whisperer']];

/* ch: the chapter whose missions must all be done before the question is played
   c: the question (HTML), a: the answer, w: wrong answers, why: shown after a miss */
RQ.QF=[
 {ch:0,c:'A name ends in <code>!</code>, like <code>println!</code>. What does the <code>!</code> mark?',a:'a macro, a built-in code writer',w:['a function that can fail','a comment','a type'],why:'A `!` after a name means a macro, not a normal function.'},
 {ch:0,c:'What does <code>{}</code> do inside the string of a <code>println!</code>?',a:'it is a hole that the next argument fills',w:['it prints two curly braces','it starts a comment','it ends the line'],why:'`println!("{}", 5)` prints `5`: the hole takes the next argument.'},
 {ch:0,c:'You write <code>let x = 5;</code> and later <code>x = 6;</code>. What does the compiler do?',a:'it stops with an error, because `x` is immutable',w:['it prints 6','it keeps 5 and ignores the line','it makes a second variable'],why:'Variables cannot change unless you add `mut`. The error code is `E0384`.'},
 {ch:0,c:'Which line makes <code>count</code> a variable you can change later?',a:'`let mut count = 0;`',w:['`let count = 0;`','`mut let count = 0;`','`let count mut = 0;`'],why:'`mut` goes right after `let`.'},
 {ch:0,c:'After <code>let pearl_price = 10;</code> comes <code>let pearl_price = pearl_price + 5;</code>. What is <code>pearl_price</code> afterwards?',a:'15, in a new variable that shadows the old one',w:['10, because the first one wins','15, in the same variable, changed in place','an error, because the name is taken'],why:'A second `let` with the same name makes a new variable, and the old one is hidden from then on.'},
 {ch:0,c:'What does <code>print!</code> do that <code>println!</code> does not?',a:'it does not start a new line afterwards',w:['it prints in capital letters','it prints twice','it only prints numbers'],why:'The `ln` in `println!` stands for line: it ends the line after printing.'},
 {ch:1,c:'What is the biggest value a <code>u8</code> can hold?',a:'255',w:['256','127','65535'],why:'A `u8` holds `0` to `255`. A `u16` goes up to `65535`.'},
 {ch:1,c:'Which expression turns the whole number <code>n</code> into an <code>f64</code>?',a:'`n as f64`',w:['`f64(n)`','`n.f64`','`n to f64`'],why:'`as` converts between number types: `n as f64`.'},
 {ch:1,c:'After <code>let t = (7, \'a\');</code>, what does <code>t.0</code> hold?',a:'7',w:['\'a\'','(7, \'a\')','nothing, it is an error'],why:'A tuple is read by position, and counting starts at `0`.'},
 {ch:1,c:'An array holds <code>[5, 6, 7]</code>. What is <code>a[1]</code>?',a:'6',w:['5','7','1'],why:'Places count from `0`, so `a[0]` is `5` and `a[1]` is `6`.'},
 {ch:1,c:'A function adds two <code>u8</code> values that come in as parameters, and the sum is <code>260</code>. What happens when it runs?',a:'the program panics and exits with code 101',w:['the sum wraps around to 4','the compiler refuses to build it','it prints 260 anyway'],why:'The compiler cannot see the numbers, so the check happens at run time and stops the program with a panic.'},
 {ch:2,c:'In <code>fn f() -> i32 { 5 }</code>, what makes <code>5</code> the value the function returns?',a:'it is the last line and has no `;`',w:['the word `return` is required','it is the biggest number','the function is called `f`'],why:'The last expression without a `;` is the value. Adding a `;` leaves nothing to return, which is `E0308`.'},
 {ch:2,c:'Which loop checks a condition before every round?',a:'`while`',w:['`for`','`if`','`let`'],why:'`while` runs its block only while the condition is true.'},
 {ch:2,c:'What numbers does <code>for i in 0..3</code> give to <code>i</code>?',a:'0, 1 and 2',w:['1, 2 and 3','0, 1, 2 and 3','only 3'],why:'`0..3` stops before `3`. Write `0..=3` to include it.'},
 {ch:2,c:'What does the error <code>E0425</code> tell you?',a:'Rust cannot find a name you used',w:['two types do not match','a value was changed twice','a number is too big'],why:'Usually a typo, or a variable used outside the block that made it.'},
 {ch:3,c:'After <code>let b = a;</code>, where <code>a</code> is a <code>String</code>, what has happened to <code>a</code>?',a:'it moved into `b`, so `a` cannot be used any more',w:['both names share the text and both still work','`a` is copied, so it works as before','`a` is cleared but can be used again'],why:'A `String` has one owner. `let b = a;` hands it to `b`, and using `a` afterwards is error `E0382`.'},
 {ch:3,c:'Which of these is copied, not moved, by <code>let b = a;</code>?',a:'an `i32`',w:['a `String`','a `String` inside a function','a `String` built with `String::from`'],why:'Numbers are `Copy`: both variables keep a usable value. A `String` owns heap memory, so it moves.'},
 {ch:3,c:'What does <code>a.clone()</code> do when <code>a</code> is a <code>String</code>?',a:'builds a second `String` with the same text',w:['moves `a` into a new name','frees `a` early','turns `a` into a number'],why:'`.clone()` copies the heap data, so the original keeps working and there are now two owners of two Strings.'},
 {ch:3,c:'<code>a</code> is declared first and <code>b</code> second, both in the same block. Which is freed first at the closing <code>}</code>?',a:'`b`, the one declared last',w:['`a`, the one declared first','they are freed at the same moment','neither: only `drop` frees a `String`'],why:'Variables are freed in the reverse order of their declaration.'},
 {ch:3,c:'A function is declared <code>fn eat(s: String)</code>. What happens to the caller\'s variable in <code>eat(meal);</code>?',a:'it moves into the function and cannot be used after the call',w:['it is copied, so it works after the call','it is borrowed and given back','it is freed before the call'],why:'A `String` parameter takes ownership. Return the `String` from the function if the caller needs it again.'},
 {ch:3,c:'What does the error <code>E0382</code> tell you?',a:'a value was used after it moved',w:['a number is too big for its type','two types do not match','a variable was changed without `mut`'],why:'Look for the `let b = a;` or the function call that took the value away.'},
 {ch:4,c:'You write <code>let r = &s;</code> where <code>s</code> is a <code>String</code>. What is <code>r</code>?',a:'a reference that borrows `s`, while `s` stays the owner',w:['a copy of the text in `s`','`s` itself, moved into a new name','a second owner of the same text'],why:'`&s` lends `s` without moving it. The loan ends after the last use of `r`.'},
 {ch:4,c:'A function takes <code>s: &String</code> and calls <code>s.push_str("!")</code>. What does the compiler do?',a:'it refuses with `E0596`, because a `&` loan cannot change the text',w:['it adds the `!` to the caller\'s `String`','it adds the `!` to a hidden copy','it builds, and panics when it runs'],why:'A `&` loan is read-only. Take a `&mut String` and lend with `&mut` to allow the change.'},
 {ch:4,c:'How many <code>&</code> loans of one <code>String</code> may be alive at the same time?',a:'as many as you like, as long as there is no `&mut` loan',w:['exactly one','two at most','none: a `String` can only be lent once'],why:'Many readers or one writer. `&` loans are readers, so they can pile up.'},
 {ch:4,c:'What does <code>&s[0..5]</code> give you when <code>s</code> is a <code>String</code>?',a:'a `&str` slice that borrows the first five bytes of `s`',w:['a new `String` that holds a copy of those bytes','the byte at place `5`','an error, because a range only works in a `for`'],why:'A slice points into the original text and copies nothing. It stops before the end number.'},
 {ch:4,c:'<code>word</code> is a slice of <code>s</code> that is printed later. What happens at <code>s.push_str("!")</code>?',a:'`E0502`: `s` is changed while a slice of it is still in use',w:['nothing, because `word` is a copy','the slice follows the text and shows the new `!`','`E0382`, because `s` moved into `word`'],why:'A slice is a loan of `s`. Use the slice up first, then change `s`.'},
 {ch:4,c:'What does the error <code>E0106</code> tell you?',a:'a function returns a reference, but Rust cannot tell which input it borrows from',w:['a reference was used after it moved','two types do not match','a number is too big for its type'],why:'It appears with no reference parameter or with two. The simple fix is to return an owned `String`; chapter 10 shows how to name the input instead.'},
 {ch:4,c:'What does the error <code>E0515</code> tell you?',a:'a function returns a reference to one of its own local variables',w:['a value was changed through a `&` loan','a `&mut` loan was made twice','a function was called with the wrong number of arguments'],why:'A local is freed when the function ends, so a reference to it would dangle. Borrow from an input or return the value.'},
 {ch:5,c:'A <code>struct</code> has the fields <code>name</code> and <code>age</code>. How do you read the age of a variable <code>pet</code>?',a:'`pet.age`',w:['`pet::age`','`pet[age]`','`age(pet)`'],why:'A dot and the field name: `pet.age`, like `t.0` for a tuple.'},
 {ch:5,c:'After <code>let pet = Pet { name: String::from("Pip"), age: 3 };</code> a later line says <code>pet.age = 4;</code>. What does the compiler do?',a:'it stops with `E0594`, because `pet` is not `mut`',w:['it sets the age to 4','it makes a second pet with age 4','it stops with `E0382`, because `pet` moved'],why:'A field can only change when the whole variable is `mut`. Write `let mut pet`.'},
 {ch:5,c:'What does <code>Pet::new("Pip", 3)</code> call?',a:'a function in `impl Pet` that has no `self` parameter',w:['a method that needs a `Pet` to be called on','a macro that builds a `Pet`','a field of `Pet` that holds a function'],why:'A function with no `self` belongs to the type, and `::` names it. A method has `self` and is called with a dot.'},
 {ch:5,c:'A method is declared <code>fn grow(&amp;mut self)</code>. What may it do?',a:'change the fields of the value it was called on',w:['only read the fields','take the value away from the caller','nothing, because `self` is not a parameter'],why:'`&mut self` is a `&mut` loan of the value. `&self` only reads and `self` takes the value.'},
 {ch:5,c:'<code>println!("{:?}", pet)</code> says the type does not implement <code>Debug</code>. What is the shortest fix?',a:'put `#[derive(Debug)]` above the `struct`',w:['write `{}` instead of `{:?}`','add `mut` to the `let`','call `pet.debug()` first'],why:'`#[derive(Debug)]` asks the compiler to write the `{:?}` printing code for you.'},
 {ch:6,c:'A <code>match</code> on an <code>enum</code> has no arm for one variant. What does the compiler do?',a:'it stops with `E0004` and names the missing variant',w:['it skips that case at run time','it runs the first arm instead','it panics when that variant arrives'],why:'A `match` must cover every value. Add the arm, or end with `_`.'},
 {ch:6,c:'What does the pattern <code>Some(n)</code> do in a <code>match</code> arm?',a:'it fits a `Some` and calls what is inside `n` for that arm',w:['it makes a new `Some` with `n` in it','it fits any `Option`, including `None`','it fits a `Some` and throws the inside away'],why:'A pattern takes a value apart. The name `n` only exists in its arm.'},
 {ch:6,c:'Which pattern fits every number from 10 up to and including 19?',a:'`10..=19`',w:['`10..19`','`10 to 19`','`[10, 19]`'],why:'`..=` includes the end. `10..19` stops before 19.'},
 {ch:6,c:'A <code>match</code> on a <code>u8</code> has the arms <code>0</code>, <code>1..=9</code> and <code>10..=99</code>. What is missing?',a:'an arm for 100 and up, for example `_`',w:['nothing, the ranges cover the number line','an arm for negative numbers','an arm for 0'],why:'A `u8` goes up to 255. `E0004` prints the numbers that are left out.'},
 {ch:6,c:'When is <code>if let Some(x) = o { ... }</code> a good fit?',a:'when only the `Some` case matters',w:['when every variant needs its own code','when `o` is a number','when you want Rust to check every case'],why:'`if let` is a `match` with one arm you care about. Use `match` when all cases matter.'},
 {ch:6,c:'What must the <code>else</code> block of a <code>let ... else</code> do?',a:'leave, with `return`, `break` or `continue`',w:['print a message and carry on below','fall through to the next line','give the name a default value'],why:'The code below uses the name the pattern made, so the `else` block must not finish normally.'},
 {ch:7,c:'<code>let first = &v[0];</code> is followed by <code>v.push(9);</code> and then a use of <code>first</code>. What does the compiler say?',a:'`E0502`: `push` needs a `&mut` loan while `first` still borrows the whole `Vec`',w:['nothing, `first` points at one slot only','`E0382`: `v` moved into `first`','`E0596`: `v` is not `mut`'],why:'A reference to one element is a loan of the whole `Vec`, because a push can move all the elements to a new place. Use `first` before the push, or copy the number out.'},
 {ch:7,c:'What does <code>v.get(5)</code> give when <code>v</code> has three elements?',a:'`None`, an `Option` with no value',w:['a panic, like `v[5]`','`0`','`Some(0)`'],why:'`get` returns an `Option<&T>`: `Some` when the place exists and `None` when it does not. Only the index form `v[5]` panics.'},
 {ch:7,c:'After <code>for x in v { ... }</code>, where <code>v</code> is a <code>Vec</code>, what happens to <code>v</code>?',a:'it moved into the loop, so it cannot be used afterwards',w:['it is unchanged and still usable','it is cleared but still usable','it becomes a `&Vec`'],why:'Looping over the `Vec` itself consumes it. Loop over `&v` to read it or `&mut v` to change it, and `v` stays yours.'},
 {ch:7,c:'A program prints a <code>HashMap</code> with three entries using <code>{:?}</code>. Why does Rust Quest refuse its output?',a:'the order of the entries changes from run to run, so the output is not fixed',w:['a `HashMap` cannot be printed','the keys are not sorted when they go in','`{:?}` only prints one entry'],why:'A `HashMap` lists its entries in a different order each run. Sort the keys into a `Vec` first, or print only things that do not depend on the order.'},
 {ch:8,c:'A function meets <code>?</code> on a <code>Result</code> that holds an <code>Err</code>. What happens?',a:'the function returns that `Err` to its caller at once',w:['the program panics','the line is skipped and the function carries on','the `Err` turns into an `Ok`'],why:'`?` opens a `Result`: `Ok(x)` becomes `x`, and `Err(e)` leaves the whole function with that `Err`. The function must return a `Result` for that to fit.'},
 {ch:8,c:'A function that returns <code>u32</code> uses <code>?</code> on a <code>Result</code>. What does the compiler say?',a:'`E0277`: `?` can only be used in a function that returns `Result` or `Option`',w:['nothing, `?` panics at run time instead','`E0382`: the `Result` moved','`E0308`: the `?` is the wrong type'],why:'An `Err` needs somewhere to go. Change the return type to `Result<u32, String>` (or the error type you use) and end the happy path with `Ok(...)`.'},
 {ch:8,c:'<code>main</code> returns <code>Result&lt;(), String&gt;</code> and ends with <code>Err(String::from("bad"))</code>. What does the program do?',a:'prints `Error: "bad"` on the error output and exits with code `1`',w:['panics and exits with code `101`','prints `bad` on standard output and exits with `0`','prints nothing and exits with `0`'],why:'Rust prints `Error: ` and the `{:?}` text of the error, so a `String` keeps its quotes, and exits with `1`. A panic exits with `101`.'},
 {ch:8,c:'After <code>let half = r?;</code> where <code>r</code> is a <code>Result&lt;u32, String&gt;</code>, what happens to a later <code>println!("{:?}", r)</code>?',a:'`E0382`: `r` moved into the `?`',w:['it prints `Ok(..)` as before','it prints the `Err`, if there was one','it compiles with a warning'],why:'`?` takes the `Result` by value, like a call that consumes it. Print `r` before the `?`, or open a copy with `r.clone()?`.'},
 {ch:9,c:"<code>fn longest&lt;'a&gt;(a: &amp;'a str, b: &amp;'a str) -&gt; &amp;'a str</code>. What does the <code>'a</code> on the result tell Rust?",a:'the answer comes from one of the inputs, so it may be used only while both are still valid',w:['the answer lives for a fixed number of lines','the answer is copied, so it is always valid','the inputs are freed as soon as the function returns'],why:"A lifetime name is a label for the compiler's check. It does not change how long anything lives. Writing it on the inputs and the result says how they are related."},
 {ch:9,c:"<code>longest</code> has one <code>'a</code> on both inputs. A caller prints its answer after the block where one input was made has ended. What does the compiler say?",a:'`E0597`: the input does not live long enough',w:['nothing, the answer was copied','`E0106`: missing lifetime specifier','`E0515`: returns a reference to a local'],why:'The signature says the answer may come from either input, so Rust keeps both borrowed for as long as the answer is used. It reports the error at the borrow of the input that is freed first.'},
 {ch:9,c:"A function has <code>'a</code> on its parameter <code>a</code> and on its result, and it may return its second parameter <code>b: &amp;str</code>, which has no name. What does the compiler say?",a:'`E0621`: explicit lifetime required in the type of `b`',w:['`E0106`: missing lifetime specifier','`E0382`: use of moved value','nothing, Rust works the lifetime out'],why:"The result promises the lifetime `'a`, and `b` was not given it. Write `b: &'a str`, or stop returning `b`."},
 {ch:9,c:'Which lifetime can a function with no reference parameter put on a reference it returns, such as a string literal?',a:"`'static`, as in `-> &'static str`",w:["`'a`, with no declaration",'none, it has to return a `String`',"`'self`"],why:"A string literal is part of the program, so a reference to it stays valid for the whole run. That lifetime is `'static`, and it needs no declaration in angle brackets."},
 {ch:9,c:'A <code>struct</code> has a field <code>text: &amp;str</code> and no lifetime name. What does the compiler say?',a:'`E0106`: missing lifetime specifier',w:['`E0382`: use of moved value','`E0308`: mismatched types','nothing, a `&str` field is fine'],why:"A `struct` that holds a reference must say how long the reference is valid. Declare a name on the `struct` and use it on the field: `struct Note<'a> { text: &'a str }`."},
 {ch:9,c:"A <code>struct Note&lt;'a&gt;</code> borrows a <code>String</code>. The <code>String</code> is freed at the end of a block, and the note is printed after it. What does the compiler say?",a:'`E0597`: the `String` does not live long enough',w:['`E0726`: implicit elided lifetime not allowed here','`E0502`: cannot borrow as mutable','nothing, the note keeps its own copy'],why:'The note holds a borrow, not a copy. It can be used only while the text it points at is still there.'},
 {ch:10,c:'A <code>trait</code> declares <code>fn sound(&amp;self) -&gt; String;</code> with no body. What must a type do to have the trait?',a:'write an `impl Trait for Type` block that defines `sound`',w:['add `#[derive(Trait)]` above the type','nothing, every type has every trait','call `sound` once from `main`'],why:'A trait is a promise. A type keeps it with `impl Trait for Type`, and Rust makes you write every method the trait lists without a body.'},
 {ch:10,c:'You call <code>crab.sound()</code>, and the type <code>Crab</code> has no <code>impl</code> of the trait that declares <code>sound</code>. What does the compiler say?',a:'`E0599`: no method named `sound` found for the `struct` `Crab`',w:['`E0277`: the trait bound is not satisfied','`E0382`: use of moved value','nothing, it picks the trait for you'],why:'Without the `impl` the method does not exist on that type. `E0277` is for passing a type that lacks a trait to code that asks for it.'},
 {ch:10,c:'<code>fn pick&lt;T&gt;(a: T, b: T) -&gt; T</code> compares <code>a &gt; b</code> in its body. What does the compiler say?',a:'`E0369`: `>` cannot be applied to `T`, because the bound is missing',w:['`E0308`: mismatched types','nothing, `>` works on every type','`E0382`: use of moved value'],why:'Inside a generic function, `T` has only what its bounds promise. Add `T: PartialOrd` and the comparison is allowed.'},
 {ch:10,c:'<code>fn show&lt;T: Display&gt;(x: T)</code> is called with a <code>Shell</code> that has no <code>impl</code> of <code>Display</code>. What does the compiler say?',a:'`E0277`: `Shell` doesn\'t implement `Display`',w:['`E0599`: no method named `show`','`E0369`: binary operation cannot be applied','nothing, `Shell` is printed as `Shell`'],why:'The caller has to meet the bound. Either write `impl fmt::Display for Shell` or pass a type that has it.'},
 {ch:10,c:'A trait method has a body inside the <code>trait</code> block. What is it called?',a:'a default method: every implementing type gets it unless it writes its own',w:['a derived method','an associated function','a required method'],why:'A method without a body must be written by each type. A default method is written once, in the trait, and shared.'},
 {ch:10,c:'Which line lets <code>?</code> turn an <code>i32</code> error into a <code>TideError</code>?',a:'`impl From<i32> for TideError`',w:['`impl Into<i32> for TideError`','`#[derive(From)]` on `TideError`','`impl TideError { fn from() }`'],why:'`?` passes the error through `From::from`. One `impl From<Source> for Target` per source type is how you teach it.'},
 {ch:10,c:'A <code>struct</code> is declared <code>struct Crate&lt;T&gt; { item: i32 }</code>. What does the compiler say?',a:'`E0392`: the type parameter `T` is never used',w:['`E0308`: mismatched types','nothing, `T` may be unused','`E0106`: missing lifetime specifier'],why:'A generic `struct` has to use each type name in a field. Use `item: T`, or remove the `<T>`.'},
 {ch:10,c:'A `struct` has an <code>impl Drop</code> whose <code>drop</code> prints its name. When does that line print?',a:'when the value goes out of scope, newest value first',w:['when the `struct` is built','only when you call `value.drop()`','at the end of the program, for every value together'],why:'Rust calls `drop` for you at the closing `}`, in reverse order of declaration. Calling `value.drop()` yourself is `E0040`.'},
 {ch:11,c:"<code>let add = |a, b| a + b;</code> What is <code>|a, b| a + b</code>?",a:"a closure: a function with no name, with its parameters between the bars",w:["a pattern that matches two values", "an `if` with two conditions", "a type that holds two numbers"],why:"A closure is written `|parameters| body`. It can be stored in a variable and called like a function: `add(2, 3)`."},
 {ch:11,c:"<code>let len = |s| s.len();</code> is called later with <code>len(\"crab\")</code>. What does the compiler say?",a:"`E0282`: type annotations needed, because `s` has no type when `s.len()` is checked",w:["`E0308`: mismatched types", "nothing, it works out `&str` from the call", "`E0599`: no method named `len`"],why:"The body is checked before the call is seen, and a method needs a known type. Write the type: `|s: &str| s.len()`."},
 {ch:11,c:"A closure reads <code>log</code>. Then <code>log.push_str(\"!\")</code> runs, and the closure is called after that. What does the compiler say?",a:"`E0502`: `log` is borrowed as mutable while the closure still holds a shared borrow",w:["`E0382`: use of moved value", "`E0499`: cannot borrow as mutable more than once", "nothing, the closure keeps its own copy"],why:"A closure borrows what it reads for as long as it can still be called. Call it before the change, or let go of it."},
 {ch:11,c:"<code>let tick = || count += 1;</code> where <code>count</code> is <code>mut</code>. <code>tick();</code> stops with <code>E0596</code>. What is missing?",a:"`mut` on the closure: `let mut tick = ...`",w:["`mut` on the call: `mut tick()`", "`move` in front of the bars", "nothing, `count` needs `&mut`"],why:"A closure that changes a capture is changed by every call, so the variable that holds it has to be `mut`."},
 {ch:11,c:"A function asks for <code>F: Fn()</code> and gets a closure that does <code>count += 1</code>. What does the compiler say?",a:"`E0525`: the closure only implements `FnMut`, not `Fn`",w:["`E0382`: use of moved value", "`E0373`: closure may outlive the function", "nothing, `count += 1` is allowed in any closure"],why:"`Fn` closures only read. A closure that changes a capture is `FnMut`, so the function has to ask for `FnMut` (and take `mut f`)."},
 {ch:11,c:"<code>fn adder(n: i32) -&gt; impl Fn(i32) -&gt; i32 { |x| x + n }</code> What does the compiler say?",a:"`E0373`: the closure may outlive `adder`, but it borrows `n`",w:["`E0106`: missing lifetime specifier", "`E0277`: the trait bound is not satisfied", "nothing, `n` is just a number"],why:"The closure borrows `n`, which is gone when `adder` returns. `move |x| x + n` makes the closure own its copy."},
 {ch:11,c:"<code>let it = v.iter().map(|x| { println!(\"{}\", x); x + 1 });</code> and nothing uses <code>it</code>. What prints?",a:"nothing, because adapters are lazy until something consumes them",w:["every item of `v`, once", "only the first item", "the program stops with an error"],why:"`map` builds a pipeline. `collect`, `sum`, `count` or a `for` loop pulls the items through it, and only then does the closure run."},
 {ch:11,c:"<code>let big: Vec&lt;i32&gt; = v.iter().filter(|n| **n &gt; 6).collect();</code> What does the compiler say?",a:"`E0277`: a `Vec<i32>` cannot be built from an iterator over `&i32`",w:["`E0282`: type annotations needed", "`E0308`: mismatched types", "nothing, `collect` copies the numbers"],why:"`iter()` gives references. Add `.copied()` before `collect`, or use `into_iter()` on a vector you own."},
 {ch:1,c:"What happens when Rust builds a program with <code>let x: u8 = 256;</code>?",a:"the build stops with the lint `overflowing_literals`",w:["`x` holds `0`, because 256 wraps around","`x` holds `255`, the biggest `u8`","the program builds and panics when it runs"],why:"A number you typed that does not fit its type is refused before the program runs."},
 {ch:2,c:"What does the error <code>E0308</code> tell you?",a:"a value has a different type from the one the place needs",w:["Rust cannot find a name you used","a variable was given a value twice","a function was called with too many arguments"],why:"Mismatched types: for example a `String` where a number is needed, or a `;` that turns the returned value into nothing."},
 {ch:2,c:"Which values does <code>for i in 1..=3</code> give to <code>i</code>?",a:"1, 2 and 3",w:["1 and 2","0, 1, 2 and 3","1, 2, 3 and 4"],why:"`..=` includes the end of the range, and `..` stops just before it."},
 {ch:5,c:"A method is declared <code>fn area(&amp;self) -&gt; u32</code> in <code>impl Rect</code>. How do you call it on a variable <code>r</code>?",a:"`r.area()`",w:["`area(r)`","`Rect.area()`","`r::area`"],why:"A method with `self` is called with a dot on the value: `r.area()`."},
 {ch:7,c:"What does <code>*m.entry(key).or_insert(0) += 1;</code> do when <code>key</code> is already in the map <code>m</code>?",a:"it adds one to the number that is already there",w:["it replaces the number with `1`","it panics, because the key exists","it adds a second entry with the same key"],why:"`or_insert` only inserts when the key is missing, and always hands back a `&mut` to the value, so the `+= 1` counts."},
 {ch:7,c:"What does <code>v.get(10)</code> give when the <code>Vec</code> <code>v</code> holds three numbers?",a:"`None`",w:["`0`","a panic","`Some(0)`"],why:"`get` gives an `Option`: `Some(&item)` when the place exists and `None` when it does not. `v[10]` would panic."},
 {ch:8,c:"What does <code>r.unwrap()</code> do when <code>r</code> is a <code>Result</code> that holds an <code>Err</code>?",a:"the program panics",w:["it gives the error as a value","it gives `0`","it returns the `Err` from the function"],why:"`unwrap` and `expect` panic on an `Err`. Only `?` returns it to the caller."},
 {ch:8,c:"In <code>fn halve(n: u32) -&gt; Result&lt;u32, String&gt;</code>, what do you write for the success case?",a:"`Ok(n / 2)`",w:["`n / 2`","`Some(n / 2)`","`Result(n / 2)`"],why:"The value is wrapped in `Ok`, so the caller can tell it from an `Err`."},
 {ch:12,c:"A function only reads a <code>Vec&lt;Find&gt;</code>, and the caller needs the <code>Vec</code> afterwards. How is the parameter written?",a:"`&Vec<Find>`, a borrow",w:["`Vec<Find>`, by value","`&mut Vec<Find>`, a mutable borrow","`Vec<&Find>`"],why:"By value moves the `Vec` into the function. A `&` borrow lets the caller keep it."},
 {ch:12,c:"<code>let kind = kind_of(name);</code> gives a <code>Result&lt;Kind, LogError&gt;</code>, and <code>Find::new(kind, 3)</code> wants a <code>Kind</code>. What does the compiler say?",a:"`E0308`: a `Result<Kind, LogError>` is not a `Kind`",w:["`E0382`: `kind` was moved","`E0599`: there is no method `new`","`E0106`: a lifetime is missing"],why:"Write `kind_of(name)?`: `?` gives the `Kind` inside the `Ok`, or returns the `Err`."},
 {ch:12,c:"<code>fn heaviest(finds: &amp;Vec&lt;Find&gt;, floor: &amp;Find) -&gt; &amp;Find</code> has two references coming in and one going out. What does the compiler say?",a:"`E0106`: it cannot tell which input the answer borrows from",w:["`E0382`: `finds` was moved","`E0499`: two `&mut` loans","`E0308`: the types do not match"],why:"Name one lifetime and put it on both inputs and on the result: `heaviest<'a>(finds: &'a Vec<Find>, floor: &'a Find) -> &'a Find`."},
 {ch:12,c:"<code>fn total&lt;T&gt;(items: &amp;Vec&lt;T&gt;)</code> calls <code>i.price()</code> on each item. What does the compiler say?",a:"`E0599`: `T` has no method `price`, until the bound `T: Priced` is added",w:["`E0382`: the items were moved","`E0277`: `T` is not `Display`","nothing, `price` is found on its own"],why:"Inside a generic function only what the bounds promise may be used."},
 {ch:12,c:"A function takes <code>rule: F</code> with <code>F: Fn(&amp;Find) -&gt; bool</code>. Which closure is accepted?",a:"one that reads a find and gives back `true` or `false`",w:["one that changes a variable it captured","one that gives back a number","only a function with a name, never a closure"],why:"`Fn` is for closures that only read what they capture. One that changes a capture is `FnMut` and is refused with `E0525`."},
 {ch:12,c:"A <code>for</code> loop calls <code>make_find(&amp;e.name, e.weight)?</code> and the second note gives an <code>Err</code>. What happens to the third note?",a:"it is never looked at, because the function returns the `Err` at once",w:["it is still processed, and the errors are collected","it is skipped and the loop goes on","the program panics"],why:"`?` returns from the whole function on an `Err`, so the loop ends there."},
 {ch:12,c:"The last line of a function returning <code>Result&lt;u32, LogError&gt;</code> is <code>Ok(total_price(&amp;finds))</code>. Why is the <code>Ok</code> there?",a:"the number has to be wrapped, because the function returns a `Result`",w:["it turns the number into a `String`","without it the number would be a reference","it is what makes `?` work"],why:"A function that can fail returns `Ok(value)` on the happy path as well."},
 {ch:12,c:"What does the error <code>E0499</code> tell you?",a:"a value is borrowed as mutable more than once at a time",w:["a value was used after it moved","a reference lives longer than its value","a closure needs a type"],why:"Only one `&mut` loan of a value may be in use at a time."}
];


/* ch: chapter; c: title; what: HTML; ex: [[code, note]], code is copied to the clipboard */
RQ.GUIDE=[
 {ch:0,c:'println! and {}',what:'<code>println!</code> prints a line of text. Put <code>{}</code> holes in the string and list one argument per hole after it. <code>print!</code> does the same without starting a new line.',
  ex:[['fn main() {\n    println!("Hello, Rust!");\n}\n','prints a line'],['fn main() {\n    println!("{} and {}", 1, "two");\n}\n','two holes, two arguments']]},
 {ch:0,c:'let and mut',what:'<code>let</code> gives a value a name. The variable cannot change unless you write <code>let mut</code>. A second <code>let</code> with the same name makes a new variable that shadows the old one.',
  ex:[['fn main() {\n    let mut lives = 3;\n    lives = lives - 1;\n    println!("{}", lives);\n}\n','<code>mut</code> allows the change'],['fn main() {\n    let pearl_price = 10;\n    let pearl_price = pearl_price + 5;\n    println!("{}", pearl_price);\n}\n','shadowing: a new variable']]},
 {ch:0,c:'E0384: assigned twice to an immutable variable',what:'The compiler says this when you give a new value to a variable made with plain <code>let</code>. Add <code>mut</code> after <code>let</code> if the value should change.',
  ex:[['fn main() {\n    let x = 5;\n    x = 6;\n}\n','this one is rejected, try it','E0384']]},
 {ch:1,c:'Number types, as and decimals',what:'Whole numbers come as <code>i32</code>, <code>i64</code> and <code>u8</code> (no negatives, <code>0</code> to <code>255</code>), among others. Decimal numbers are <code>f64</code>. Rust never mixes types for you: <code>as</code> converts, so <code>n as f64</code> gives a decimal copy of <code>n</code>.',
  ex:[['fn main() {\n    let coins: i32 = 7;\n    let price: f64 = 2.5;\n    println!("{}", coins as f64 * price);\n}\n','<code>as</code> makes the types match'],['fn main() {\n    let x: f64 = 2;\n}\n','rejected: <code>2</code> is a whole number, write <code>2.0</code>','E0308']]},
 {ch:1,c:'Tuples, arrays and {:?}',what:'A tuple groups values of different types, read by place with <code>t.0</code>. An array holds values of one type, read with <code>a[1]</code>. Places count from <code>0</code>. Print a whole tuple or array with the <code>{:?}</code> hole.',
  ex:[['fn main() {\n    let pet = ("Pip", 3);\n    let shelf = [10, 20, 30];\n    println!("{} {} {:?}", pet.0, shelf[1], shelf);\n}\n','one tuple, one array']]},
 {ch:1,c:'arithmetic_overflow, overflowing_literals and unconditional_panic',what:'These lints are checks the compiler runs on its own, and each stops the build. <code>arithmetic_overflow</code>: a sum it can work out is too big for its type. <code>overflowing_literals</code>: a number you typed does not fit its type. <code>unconditional_panic</code>: something that always fails, like dividing by zero or a place past the end of an array.',
  ex:[['fn main() {\n    let x: u8 = 255 + 1;\n}\n','rejected: <code>arithmetic_overflow</code>','arithmetic_overflow'],['fn main() {\n    let x: u8 = 256;\n}\n','rejected: <code>overflowing_literals</code>','overflowing_literals'],['fn main() {\n    println!("{}", 1 / 0);\n}\n','rejected: <code>unconditional_panic</code>','unconditional_panic']]},
 {ch:1,c:'panic',what:'A panic is how a Rust program stops itself when it cannot go on, for example when a sum overflows at run time. The program prints a message on the error output and exits with code <code>101</code>. What it printed before stays.',
  ex:[['fn add(a: u8, b: u8) -> u8 {\n    a + b\n}\n\nfn main() {\n    println!("before");\n    println!("{}", add(250, 10));\n}\n','builds, then panics','panic']]},
 {ch:2,c:'E0308: mismatched types',what:'The compiler says this when a value has one type and the place it goes needs another: a <code>let</code> with a type, an argument, a returned value, the two parts of an <code>if</code> and <code>else</code>, or a condition that is not <code>true</code> or <code>false</code>. A stray <code>;</code> after the last line of a function does it too.',
  ex:[['fn main() {\n    let x: i32 = "a";\n}\n','rejected, try it','E0308'],['fn add_one(n: i32) -> i32 {\n    n + 1;\n}\n\nfn main() {\n    println!("{}", add_one(1));\n}\n','rejected: the <code>;</code> returns nothing','E0308']]},
 {ch:2,c:'E0425: cannot find a name',what:'The compiler says this when you use a variable or function it does not know: a typo, a name used before it is made, or a variable that lived in a block that already ended.',
  ex:[['fn main() {\n    let shells = 1;\n    println!("{}", shell);\n}\n','rejected, try it','E0425']]},
 {ch:2,c:'if, loop, while and for',what:'<code>if</code> and <code>else</code> choose, and the pair also gives a value. <code>loop</code> repeats until a <code>break</code>, which can carry a value. <code>while</code> repeats while a condition holds. <code>for i in 1..=5</code> walks through a range; <code>1..5</code> stops before <code>5</code>.',
  ex:[['fn main() {\n    let mut total = 0;\n    for i in 1..=5 {\n        total = total + i;\n    }\n    let label = if total > 10 { 1 } else { 0 };\n    println!("{} {}", total, label);\n}\n','a <code>for</code> and an <code>if</code> together']]},
 {ch:3,c:'String, push_str and the heap',what:'A <code>String</code> is text that can grow. The letters live on the heap and the variable on the stack holds a note about where they are. <code>String::from("hi")</code> makes one, <code>s.push_str("!")</code> adds to it, and the variable must be <code>let mut</code> for that. <code>println!("{}", s)</code> leaves it usable.',
  ex:[['fn main() {\n    let mut s = String::from("ahoy");\n    s.push_str(", Rust");\n    println!("{}", s);\n}\n','one String that grows']]},
 {ch:3,c:'E0382: use of a moved value',what:'A <code>String</code> has one owner. <code>let b = a;</code> and passing it to a function both move it, and using the old name afterwards is <code>E0382</code>. Use the new owner, return the value from the function, or make a copy with <code>.clone()</code>.',
  ex:[['fn main() {\n    let a = String::from("hi");\n    let b = a;\n    println!("{}", a);\n}\n','rejected: <code>a</code> moved to <code>b</code>','E0382'],['fn main() {\n    let a = String::from("hi");\n    let b = a.clone();\n    println!("{} {}", a, b);\n}\n','accepted: <code>.clone()</code> makes a second String']]},
 {ch:3,c:'Copy types and clone',what:'Numbers, <code>bool</code> and <code>char</code> are <code>Copy</code>: <code>let b = a;</code> copies them and both names keep working. A <code>String</code> is not <code>Copy</code>, so you ask for a copy with <code>.clone()</code>, which builds a second <code>String</code> on the heap.',
  ex:[['fn main() {\n    let a = 7;\n    let b = a;\n    println!("{} {}", a, b);\n}\n','a number is copied']]},
 {ch:3,c:'drop and the order things are freed',what:'Rust frees a variable when it goes out of scope, in the reverse order of declaration. <code>drop(x)</code> frees <code>x</code> earlier, and moves it, so <code>x</code> cannot be used afterwards. A function that takes a <code>String</code> frees it at its end unless it returns it.',
  ex:[['fn main() {\n    let first = String::from("one");\n    let second = String::from("two");\n    drop(first);\n    println!("{}", second);\n}\n','<code>first</code> is freed early']]},
 {ch:4,c:'& and &mut: borrowing',what:'<code>&s</code> lends <code>s</code> without moving it, and the owner keeps ownership. A <code>&</code> loan is read-only and any number of them may exist at once. A <code>&mut</code> loan may change the value, and while it is in use nothing else may look at the value. A loan lasts until its last use. A function takes a loan with a parameter such as <code>s: &String</code> or <code>s: &mut String</code>.',
  ex:[['fn len_of(s: &String) -> usize {\n    s.len()\n}\n\nfn main() {\n    let s = String::from("ahoy");\n    println!("{} {}", len_of(&s), s);\n}\n','<code>s</code> is lent and still usable'],['fn exclaim(s: &mut String) {\n    s.push_str("!");\n}\n\nfn main() {\n    let mut s = String::from("hey");\n    exclaim(&mut s);\n    println!("{}", s);\n}\n','<code>&mut</code> lets the function change it']]},
 {ch:4,c:'E0502: borrowed as mutable and as immutable',what:'The compiler says this when a <code>&mut</code> loan (or a call such as <code>push_str</code> that needs one) starts while a <code>&</code> loan of the same value is still going to be used. Use the <code>&</code> loan up first, then change the value.',
  ex:[['fn main() {\n    let mut s = String::from("ahoy");\n    let r = &s;\n    s.push_str("!");\n    println!("{}", r);\n}\n','rejected: <code>r</code> is used after the change','E0502'],['fn main() {\n    let mut s = String::from("ahoy");\n    let r = &s;\n    println!("{}", r);\n    s.push_str("!");\n}\n','accepted: <code>r</code> is finished first']]},
 {ch:4,c:'E0596: borrowed as mutable, but it cannot change',what:'The compiler says this when you try to change a value through a <code>&</code> loan, or borrow a variable with <code>&mut</code> when it was not declared with <code>let mut</code>. Take a <code>&mut</code> parameter, or add <code>mut</code> to the <code>let</code>.',
  ex:[['fn add(s: &String) {\n    s.push_str("!");\n}\n\nfn main() {\n    let mut s = String::from("hey");\n    add(&s);\n}\n','rejected: a <code>&</code> loan is read-only','E0596']]},
 {ch:4,c:'Slices: &s[0..5]',what:'A slice borrows part of a value and copies nothing. <code>&s[0..5]</code> is the text from byte <code>0</code> up to, but not including, byte <code>5</code>, and it has the type <code>&str</code>. <code>&s[..5]</code> and <code>&s[6..]</code> leave one end open. A range that reaches past the end panics at run time. A slice is a loan of the whole value.',
  ex:[['fn main() {\n    let s = String::from("hello world");\n    println!("{} {}", &s[..5], &s[6..]);\n}\n','two words, no copies'],['fn main() {\n    let a = [10, 20, 30, 40];\n    println!("{:?}", &a[1..3]);\n}\n','an array slice prints like an array']]},
 {ch:4,c:'E0106: missing lifetime specifier',what:'The compiler says this when a function returns a reference and Rust cannot tell which input it borrows from: there is no reference parameter, or there are two or more. The simple fix is to return an owned <code>String</code> instead; chapter 10 shows how to name the input.',
  ex:[['fn longest(a: &str, b: &str) -> &str {\n    a\n}\n\nfn main() {\n    println!("{}", longest("a", "bb"));\n}\n','rejected: which input does the result borrow?','E0106']]},
 {ch:4,c:'E0515: returning a reference to a local',what:'The compiler says this when a function returns a reference to one of its own local variables, or to a slice of one. The local is freed when the function ends, so the reference would point at nothing. Borrow from an input instead, or return the value itself.',
  ex:[['fn make(s: &str) -> &str {\n    let t = s.to_owned();\n    &t\n}\n\nfn main() {\n    println!("{}", make("hi"));\n}\n','rejected: <code>t</code> is freed when <code>make</code> ends','E0515']]},
 {ch:5,c:'struct, impl and methods',what:'A <code>struct</code> groups named fields. <code>impl Name { ... }</code> adds functions that belong to it. A function with no <code>self</code> is called with <code>Name::f()</code>. A method takes <code>&amp;self</code> to read, <code>&amp;mut self</code> to change or <code>self</code> to use the value up, and is called with a dot. <code>#[derive(Debug)]</code> lets <code>{:?}</code> print the whole thing.',
  ex:[['#[derive(Debug)]\nstruct Rect {\n    w: u32,\n    h: u32,\n}\n\nimpl Rect {\n    fn new(w: u32, h: u32) -> Rect {\n        Rect { w, h }\n    }\n\n    fn area(&self) -> u32 {\n        self.w * self.h\n    }\n}\n\nfn main() {\n    let r = Rect::new(3, 4);\n    println!("{} {:?}", r.area(), r);\n}\n','a function, a method and a printout']]},
 {ch:5,c:'E0594: cannot assign to a field',what:'The compiler says this when you change a field of a variable that is not <code>mut</code>, or through a plain <code>&amp;</code> loan such as <code>&amp;self</code>. Make the variable <code>let mut</code>, or take <code>&amp;mut self</code>.',
  ex:[['struct Counter {\n    n: u32,\n}\n\nfn main() {\n    let c = Counter { n: 0 };\n    c.n = 1;\n    println!("{}", c.n);\n}\n','rejected: <code>c</code> is not <code>mut</code>','E0594']]},
 {ch:6,c:'enum and match',what:'An <code>enum</code> lists the choices a value can be, and a variant can carry data. A <code>match</code> compares a value with patterns from the top down and the first fit wins. It must cover every value: <code>E0004</code> names what is missing, and a last arm <code>_</code> catches the rest. Patterns can be numbers, ranges like <code>1..=5</code>, several choices with <code>|</code>, names, <code>_</code>, tuples, and variants taken apart, and an arm can add an <code>if</code> guard.',
  ex:[['enum Shape {\n    Dot,\n    Square(u32),\n    Rect { w: u32, h: u32 },\n}\n\nfn area(s: Shape) -> u32 {\n    match s {\n        Shape::Dot => 0,\n        Shape::Square(side) => side * side,\n        Shape::Rect { w, h } => w * h,\n    }\n}\n\nfn main() {\n    println!("{} {}", area(Shape::Square(3)), area(Shape::Rect { w: 2, h: 5 }));\n}\n','every variant has an arm'],['fn main() {\n    let n: u8 = 7;\n    let size = match n {\n        0 => 0,\n        1..=9 => 1,\n    };\n    println!("{}", size);\n}\n','rejected: 10 and up are left out','E0004']]},
 {ch:6,c:'Option, if let, while let and let else',what:'<code>Option</code> is an <code>enum</code> that is either <code>Some(value)</code> or <code>None</code>. When only one case matters, <code>if let Some(x) = o { ... }</code> runs the block for that case, <code>while let</code> repeats while the pattern fits, and <code>let Some(x) = o else { return; };</code> leaves early otherwise. A plain <code>let</code> with a pattern that can fail, like <code>let Some(x) = o;</code>, is <code>E0005</code>.',
  ex:[['fn main() {\n    let o = Some(5);\n    if let Some(n) = o {\n        println!("got {}", n);\n    }\n}\n','one case only'],['fn main() {\n    let o = Some(5);\n    let Some(n) = o;\n    println!("{}", n);\n}\n','rejected: <code>None</code> would not fit','E0005']]},
 {ch:7,c:'Vec: a list that grows',what:'A <code>Vec&lt;T&gt;</code> owns a list of values of one type, and it grows with <code>push</code>. <code>vec![1, 2, 3]</code> makes one with values, <code>Vec::new()</code> an empty one. <code>len()</code> counts, <code>pop()</code> takes the last one out as an <code>Option</code>, <code>get(i)</code> looks at place <code>i</code> as an <code>Option</code>, and <code>v[i]</code> reads place <code>i</code> and panics when there is none. A reference to an element, like <code>&amp;v[0]</code>, is a loan of the whole <code>Vec</code>, so the <code>Vec</code> cannot change while the reference is in use.',
  ex:[['fn main() {\n    let mut v = vec![4, 8];\n    v.push(15);\n    println!("{:?} {} {:?}", v, v.len(), v.get(7));\n}\n','a list that grows, and a <code>get</code> that gives <code>None</code>'],['fn main() {\n    let v = vec![4, 8, 15];\n    let i = v.len() + 4;\n    println!("{}", v[i]);\n}\n','panics: the index is past the end','panic'],['fn main() {\n    let mut v = vec![4, 8, 15];\n    let first = &v[0];\n    v.push(16);\n    println!("{}", first);\n}\n','rejected: <code>first</code> is used after the push','E0502']]},
 {ch:7,c:'for over a collection',what:'<code>for x in &amp;v</code> lends the <code>Vec</code> and gives a reference to each element, <code>for x in &amp;mut v</code> gives a <code>&amp;mut</code> to each so the loop can change them, and <code>for x in v</code> moves the <code>Vec</code> into the loop and gives each element by value. A loop over a loan holds that loan until it ends, so the <code>Vec</code> cannot be pushed to inside the loop: that is <code>E0502</code> (or <code>E0499</code> for <code>&amp;mut</code>).',
  ex:[['fn main() {\n    let mut v = vec![1, 2, 3];\n    for x in &mut v {\n        *x *= 10;\n    }\n    let mut total = 0;\n    for x in &v {\n        total += *x;\n    }\n    println!("{:?} {}", v, total);\n}\n','change in place, then read'],['fn main() {\n    let mut v = vec![1, 2, 3];\n    for x in &v {\n        v.push(*x);\n    }\n}\n','rejected: the loop still borrows <code>v</code>','E0502'],['fn main() {\n    let v = vec![1, 2, 3];\n    for x in v {\n        println!("{}", x);\n    }\n    println!("{}", v.len());\n}\n','rejected: the loop used <code>v</code> up','E0382']]},
 {ch:7,c:'HashMap: look up by key',what:'A <code>HashMap&lt;K, V&gt;</code> finds a value by its key. Bring it in with <code>use std::collections::HashMap;</code>. <code>insert(k, v)</code> adds, <code>get(&amp;k)</code> gives an <code>Option&lt;&amp;V&gt;</code>, <code>contains_key</code> asks, <code>remove</code> takes an entry out, and <code>*m.entry(k).or_insert(0) += 1</code> adds to a count and starts it at <code>0</code> when the key is new. A map has no order: real Rust lists its entries differently on every run, so Rust Quest runs your program twice with two orders and refuses an output that changes. Sort the keys into a <code>Vec</code> to print in a fixed order.',
  ex:[['use std::collections::HashMap;\n\nfn main() {\n    let mut m: HashMap<String, u32> = HashMap::new();\n    for w in vec![String::from("a"), String::from("b"), String::from("a")] {\n        *m.entry(w).or_insert(0) += 1;\n    }\n    println!("{:?} {:?} {}", m.get("a"), m.get("z"), m.len());\n}\n','a count per key, and a missing key is <code>None</code>']]},
 {ch:8,c:'Result: ok or an error',what:'A <code>Result&lt;T, E&gt;</code> is either <code>Ok(value)</code>, with a <code>T</code>, or <code>Err(reason)</code>, with an <code>E</code>. A function that can fail returns one, and the caller opens it with <code>match</code>, or with <code>expect</code> and <code>unwrap</code> when a failure would be a bug: those panic on an <code>Err</code> and show it with <code>{:?}</code>. <code>ok_or</code> turns an <code>Option</code> into a <code>Result</code> by naming the error for <code>None</code>.',
  ex:[['fn halve(n: u32) -> Result<u32, String> {\n    if n % 2 == 0 {\n        Ok(n / 2)\n    } else {\n        Err(format!("{} is odd", n))\n    }\n}\n\nfn main() {\n    match halve(8) {\n        Ok(h) => println!("half {}", h),\n        Err(e) => println!("no: {}", e),\n    }\n    println!("{:?}", halve(7));\n}\n','one function, both answers'],['fn halve(n: u32) -> Result<u32, String> {\n    if n % 2 == 0 { Ok(n / 2) } else { Err(format!("{} is odd", n)) }\n}\n\nfn main() {\n    println!("{}", halve(7).expect("an even number"));\n}\n','panics: expect on an Err','panic']]},
 {ch:8,c:'? passes an error up',what:'<code>?</code> after a <code>Result</code> gives the value inside an <code>Ok</code>, and on an <code>Err</code> it returns that <code>Err</code> from the whole function. The function must return a <code>Result</code> with the same error type, or the compiler stops with <code>E0277</code>. <code>?</code> takes the <code>Result</code> by value, so using it afterwards is <code>E0382</code>. Turning one error type into another with <code>?</code> needs an <code>impl From</code>, which chapter 11 teaches.',
  ex:[['fn halve(n: u32) -> Result<u32, String> {\n    if n % 2 == 0 { Ok(n / 2) } else { Err(format!("{} is odd", n)) }\n}\n\nfn quarter(n: u32) -> Result<u32, String> {\n    let h = halve(n)?;\n    halve(h)\n}\n\nfn main() {\n    println!("{:?} {:?}", quarter(12), quarter(6));\n}\n','an Err leaves quarter early'],['fn halve(n: u32) -> Result<u32, String> {\n    if n % 2 == 0 { Ok(n / 2) } else { Err(format!("{} is odd", n)) }\n}\n\nfn main() {\n    let h = halve(8)?;\n    println!("{}", h);\n}\n','rejected: main returns nothing for the ? to use','E0277']]},
 {ch:8,c:'main can return a Result',what:'<code>fn main() -&gt; Result&lt;(), E&gt;</code> lets <code>?</code> work inside <code>main</code>, with <code>Ok(())</code> as the last line. If <code>main</code> returns an <code>Err</code>, the program prints <code>Error: </code> and the <code>{:?}</code> text of the error on the error output and exits with code <code>1</code>. <code>E</code> must have <code>Debug</code>, so a <code>#[derive(Debug)]</code> <code>enum</code> makes a good error type.',
  ex:[['#[derive(Debug)]\nenum ShareError {\n    Odd(u32),\n}\n\nfn split(n: u32) -> Result<u32, ShareError> {\n    if n % 2 == 1 { Err(ShareError::Odd(n)) } else { Ok(n / 2) }\n}\n\nfn main() -> Result<(), ShareError> {\n    println!("{}", split(8)?);\n    println!("{}", split(7)?);\n    Ok(())\n}\n','prints 4, then Error: Odd(7) and exit code 1']]},
 {ch:9,c:'Lifetime names',what:"A lifetime name like <code>'a</code> labels how references relate. Declare it in angle brackets after a <code>fn</code> or <code>struct</code> name, then write it after the <code>&amp;</code>: <code>fn longest&lt;'a&gt;(a: &amp;'a str, b: &amp;'a str) -&gt; &amp;'a str</code>. The label does not change how long anything lives. It tells Rust the answer comes from the inputs that carry it, so the answer may be used only while they are valid. Errors: <code>E0106</code> when a result has no label to use, <code>E0261</code> when a name was never declared, <code>E0621</code> when a returned parameter lacks the result's label, and <code>E0597</code> when the answer outlives one of its inputs. <code>'static</code> is the lifetime of the whole run, which a string literal has.",
  ex:[["fn longest<'a>(a: &'a str, b: &'a str) -> &'a str {\n    if a.len() > b.len() { a } else { b }\n}\n\nfn main() {\n    let big = String::from(\"bigger\");\n    let small = String::from(\"tiny\");\n    println!(\"{}\", longest(&big, &small));\n}\n",'one name on both inputs and the result'],["fn greeting() -> &'static str {\n    \"hello\"\n}\n\nfn main() {\n    println!(\"{}\", greeting());\n}\n",'a literal lives for the whole run']]},
 {ch:9,c:'A struct that holds a reference',what:"A <code>struct</code> whose field is a reference declares a lifetime and uses it on the field: <code>struct Note&lt;'a&gt; { text: &amp;'a str }</code>. Its <code>impl</code> declares the name again and gives it to the type: <code>impl&lt;'a&gt; Note&lt;'a&gt;</code> (or <code>impl Note&lt;'_&gt;</code>), and leaving it out is <code>E0726</code>. The note can be used only while the text it points at is valid, and a method that returns a reference with <code>&amp;self</code> keeps the note, and so the text, borrowed while the result is used.",
  ex:[["struct Note<'a> {\n    text: &'a str,\n}\n\nimpl<'a> Note<'a> {\n    fn start(&self) -> &str {\n        &self.text[..4]\n    }\n}\n\nfn main() {\n    let words = String::from(\"meet at low tide\");\n    let note = Note { text: &words };\n    println!(\"{}\", note.start());\n}\n",'the note borrows words; start borrows the note']]},
 {ch:10,c:'Traits and impl',what:"A <code>trait</code> lists methods a type can promise, and <code>impl Trait for Type</code> keeps the promise by writing each one with the same signature. A method with a body in the <code>trait</code> is a default every type gets; an <code>impl</code> may replace it. Errors: <code>E0599</code> when a type has no <code>impl</code> of the trait that has the method, <code>E0046</code> when an <code>impl</code> leaves out a method without a default, <code>E0407</code> when it adds one the trait does not list, and <code>E0119</code> for two impls of one trait for one type.",
  ex:[["trait Cry {\n    fn name(&self) -> String;\n    fn sound(&self) -> String;\n    fn intro(&self) -> String {\n        format!(\"{} says {}\", self.name(), self.sound())\n    }\n}\n\nstruct Crab {\n    name: String,\n}\n\nimpl Cry for Crab {\n    fn name(&self) -> String {\n        self.name.clone()\n    }\n    fn sound(&self) -> String {\n        String::from(\"click\")\n    }\n}\n\nfn main() {\n    let c = Crab { name: String::from(\"Pip\") };\n    println!(\"{}\", c.intro());\n}\n",'intro is a default method, name and sound are the crab\'s own'],["trait Cry {\n    fn sound(&self) -> String;\n}\n\nstruct Crab;\n\nfn main() {\n    println!(\"{}\", Crab.sound());\n}\n",'rejected: the crab has no <code>impl</code> of <code>Cry</code>',"E0599"]]},
 {ch:10,c:'Generic functions and bounds',what:"<code>fn largest&lt;T: PartialOrd&gt;(a: T, b: T) -&gt; T</code> declares a type name <code>T</code> and a bound after the colon. The body may use only what the bounds promise: <code>PartialOrd</code> opens <code>&lt;</code> and <code>&gt;</code>, <code>PartialEq</code> opens <code>==</code>, <code>Clone</code> opens <code>.clone()</code>, and a trait of yours opens its methods. Without the bound the body is <code>E0369</code> (an operator), <code>E0599</code> (a method) or <code>E0277</code> (printing with <code>{}</code>). A call must meet the bound, or it is <code>E0277</code> at the argument. <code>where T: PartialOrd</code> and a parameter written <code>x: &amp;impl Trait</code> say the same.",
  ex:[["fn larger<T: PartialOrd>(a: T, b: T) -> T {\n    if a > b { a } else { b }\n}\n\nfn main() {\n    println!(\"{} {}\", larger(3, 9), larger(2.5, 1.5));\n}\n",'one function, two number types'],["fn larger<T>(a: T, b: T) -> T {\n    if a > b { a } else { b }\n}\n\nfn main() {\n    println!(\"{}\", larger(3, 9));\n}\n",'rejected: T has no bound for >',"E0369"]]},
 {ch:10,c:'Display, to_string and Drop',what:"<code>{}</code> needs <code>impl fmt::Display for Type</code>, with <code>fn fmt(&amp;self, f: &amp;mut fmt::Formatter) -&gt; fmt::Result</code> that ends in <code>write!(f, ...)</code>. It also gives <code>to_string()</code>. Without it, <code>{}</code> on your type is <code>E0277</code>. <code>impl Drop for Type</code> with <code>fn drop(&amp;mut self)</code> runs when a value goes out of scope, newest first. Calling <code>value.drop()</code> yourself is <code>E0040</code>.",
  ex:[["use std::fmt;\n\nstruct Shell {\n    size: u32,\n}\n\nimpl fmt::Display for Shell {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, \"shell:{}\", self.size)\n    }\n}\n\nimpl Drop for Shell {\n    fn drop(&mut self) {\n        println!(\"dropping {}\", self.size);\n    }\n}\n\nfn main() {\n    let s = Shell { size: 4 };\n    println!(\"{}\", s);\n}\n",'printed with <code>{}</code>, dropped at the end']]},
 {ch:10,c:'From and ? between errors',what:"<code>impl From&lt;i32&gt; for TideError</code> says how to build a <code>TideError</code> from an <code>i32</code>. <code>?</code> calls it on the error, so a function can return its own error type even when it calls functions that fail with others. <code>TideError::from(7)</code> and <code>7.into()</code> use the same <code>impl</code>. With no matching <code>impl</code>, the <code>?</code> is <code>E0277</code>, and so is <code>into</code>.",
  ex:[["#[derive(Debug)]\nenum TideError {\n    TooLow(i32),\n}\n\nimpl From<i32> for TideError {\n    fn from(n: i32) -> TideError {\n        TideError::TooLow(n)\n    }\n}\n\nfn check(depth: i32) -> Result<i32, i32> {\n    if depth < 0 { Err(depth) } else { Ok(depth) }\n}\n\nfn plan(depth: i32) -> Result<i32, TideError> {\n    let d = check(depth)?;\n    Ok(d * 2)\n}\n\nfn main() {\n    println!(\"{:?} {:?}\", plan(5), plan(-3));\n}\n",'the <code>i32</code> error becomes a <code>TideError</code> at the <code>?</code>']]},
 {ch:10,c:'Generic structs and enums',what:"A type takes type names in angle brackets: <code>struct Crate&lt;T&gt; { item: T }</code>, and an <code>enum</code> the same way. Its <code>impl</code> declares the name again, <code>impl&lt;T&gt; Crate&lt;T&gt;</code>. <code>Crate { item: 3 }</code> is a <code>Crate&lt;i32&gt;</code>, and each use is checked on its own. <code>impl Crate&lt;i32&gt;</code> gives methods to that one only, and <code>impl&lt;T: Display&gt; Crate&lt;T&gt;</code> to crates whose item can be shown; calling a method elsewhere is <code>E0599</code>. A name that no field uses is <code>E0392</code>, and writing <code>Crate</code> with no type is <code>E0107</code>.",
  ex:[["struct Crate<T> {\n    item: T,\n}\n\nimpl<T> Crate<T> {\n    fn open(&self) -> &T {\n        &self.item\n    }\n}\n\nfn main() {\n    let a = Crate { item: 3 };\n    let b = Crate { item: String::from(\"shell\") };\n    println!(\"{} {}\", a.open(), b.open());\n}\n",'one definition, two crates']]},
 {ch:11,c:"Closures",what:"A closure is a function written in place: <code>|x| x + 1</code>, with the parameters between the bars and the body after them. Store it in a variable and call it like a function. Types may be left out when Rust can work them out, but a method call on a parameter needs one (<code>E0282</code>). Calling it with the wrong number of arguments is <code>E0057</code>, and calling something that is not a function, like a number, is <code>E0618</code>.",
  ex:[["fn main() {\n    let tally = |word: &str| word.len();\n    println!(\"{}\", tally(\"shell\"));\n    println!(\"{}\", tally(\"crab\"));\n}\n", "one closure, called twice"]]},
 {ch:11,c:"What a closure captures",what:"A closure uses the variables around it. It <em>borrows</em> them by default: a shared borrow when it only reads (<code>E0502</code> if the variable changes before the last call), a <code>&amp;mut</code> borrow when it changes them, which makes the closure itself need <code>mut</code> to be called (<code>E0596</code>). Assigning to a captured variable that is not <code>mut</code> is <code>E0594</code>. <code>move</code> before the bars makes the closure own its captures instead, and a closure that leaves its function needs it (<code>E0373</code>).",
  ex:[["fn main() {\n    let mut count = 0;\n    let mut tick = || count += 1;\n    tick();\n    tick();\n    println!(\"{}\", count);\n    let name = String::from(\"Pip\");\n    let greet = move || println!(\"hi {}\", name);\n    greet();\n}\n", "a closure that changes a capture, and one that owns its capture"]]},
 {ch:11,c:"Fn, FnMut, FnOnce and impl Fn",what:"A closure's kind comes from its body: <code>Fn</code> only reads, <code>FnMut</code> changes a capture, <code>FnOnce</code> moves one out. A function takes a closure with a bound, <code>F: Fn(i32) -&gt; i32</code> or <code>impl Fn(i32) -&gt; i32</code>, and hands one back with <code>-&gt; impl Fn(i32) -&gt; i32</code>. Ask for the weakest kind you can live with; a closure that is too weak is <code>E0525</code>. A closure with the wrong number of parameters is <code>E0593</code>, and with the wrong parameter type <code>E0631</code>.",
  ex:[["fn apply<F: Fn(i32) -> i32>(f: F, x: i32) -> i32 {\n    f(x)\n}\n\nfn run_twice<F: FnMut()>(mut f: F) {\n    f();\n    f();\n}\n\nfn main() {\n    let bonus = 3;\n    println!(\"{}\", apply(|n| n + bonus, 4));\n    let mut count = 0;\n    run_twice(|| count += 1);\n    println!(\"{}\", count);\n}\n", "a closure as a parameter, in two kinds"]]},
 {ch:11,c:"Iterators and adapters",what:"<code>iter()</code>, <code>iter_mut()</code> and <code>into_iter()</code> start an iterator, and <code>0..5</code> is one too. Adapters such as <code>map</code>, <code>filter</code>, <code>enumerate</code>, <code>zip</code>, <code>rev</code>, <code>take</code> and <code>skip</code> wrap it and are lazy: nothing runs until a consumer asks for the items. Consumers are <code>collect</code>, <code>sum</code>, <code>count</code>, <code>fold</code>, <code>any</code>, <code>all</code>, <code>find</code>, <code>position</code>, <code>min</code>, <code>max</code> and the <code>for</code> loop. <code>collect</code> needs the type you want, on the variable or as <code>collect::&lt;Vec&lt;i32&gt;&gt;()</code>; without it Rust says <code>E0282</code> or <code>E0283</code>.",
  ex:[["fn main() {\n    let shells = vec![2, 5, 9];\n    let doubled = shells.iter().map(|n| {\n        println!(\"doubling {}\", n);\n        n * 2\n    });\n    println!(\"before\");\n    let list: Vec<i32> = doubled.collect();\n    println!(\"{:?}\", list);\n}\n", "nothing runs until collect"]]},
 {ch:11,c:"Items of an iterator",what:"<code>v.iter()</code> gives <code>&amp;T</code>, <code>v.iter_mut()</code> gives <code>&amp;mut T</code>, and <code>v.into_iter()</code> on a vector you own gives <code>T</code>. A <code>filter</code> closure gets a reference to the item, so with <code>iter()</code> it is a <code>&amp;&amp;i32</code> and needs <code>**n &gt; 6</code>. <code>copied()</code> and <code>cloned()</code> turn the references into values, and building a <code>Vec&lt;i32&gt;</code> or a sum of <code>i32</code> from references is <code>E0277</code>.",
  ex:[["fn main() {\n    let shells = vec![3, 8, 12, 5, 20];\n    let big: Vec<i32> = shells.iter().filter(|n| **n > 6).copied().collect();\n    println!(\"{:?}\", big);\n    let total: i32 = big.iter().sum();\n    println!(\"{}\", total);\n    println!(\"{:?}\", shells.iter().position(|n| *n == 12));\n}\n", "`filter`, `copied`, `collect`, `sum` and `position`"]]},
 {ch:11,c:"Closures in Option, Vec and HashMap",what:"<code>Option</code> and <code>Result</code> take closures in <code>map</code>, <code>and_then</code> and <code>unwrap_or_else</code>, which runs its closure only when there is no value. A <code>Vec</code> has <code>retain(|x| ...)</code> to keep items and <code>sort_by_key(|x| ...)</code> to sort by a key. A <code>HashMap</code> has <code>entry(key).or_insert_with(|| value)</code>, which builds the value only for a missing key.",
  ex:[["fn main() {\n    let mut sizes = vec![30, 5, 18, 2, 9];\n    sizes.retain(|s| *s > 4);\n    sizes.sort_by_key(|s| -*s);\n    println!(\"{:?}\", sizes);\n    let top = sizes.first().map(|s| s * 2).unwrap_or_else(|| 0);\n    println!(\"{}\", top);\n}\n", "`retain`, `sort_by_key`, `map` and `unwrap_or_else`"]]},
 {ch:12,gl:1,c:"E0381, E0415 and E0428: names and values",what:"<code>E0381</code>: a variable is used before it has a value, for example a <code>let</code> with only a type. <code>E0415</code>: two parameters of one function have the same name. <code>E0428</code>: two items, such as functions or constants, are defined with the same name.",
  ex:[["fn main() {\n    let x: i32;\n    println!(\"{}\", x);\n}\n", "rejected: <code>E0381</code>, <code>x</code> has no value yet", "E0381"], ["fn pick(a: i32, a: i32) -> i32 {\n    a\n}\n\nfn main() {\n    println!(\"{}\", pick(1, 2));\n}\n", "rejected: <code>E0415</code>, two parameters called <code>a</code>", "E0415"], ["fn f() {}\n\nfn f() {}\n\nfn main() {\n    f();\n    f();\n}\n", "rejected: <code>E0428</code>, two functions called <code>f</code>", "E0428"]]},
 {ch:12,gl:1,c:"E0499, E0505, E0506, E0507, E0597 and E0621: loans and moves",what:"<code>E0499</code>: a second <code>&mut</code> loan starts while the first is still in use. <code>E0505</code>: a value moves while a loan of it is still in use. <code>E0506</code>: a variable is assigned while a loan of it is still in use. <code>E0507</code>: a value is moved out of something that keeps it, such as a <code>Vec</code> element. <code>E0597</code>: a loan outlives the value it borrows, which went out of scope. <code>E0621</code>: a function returns a reference that carries a lifetime name, but takes it from a parameter that has none.",
  ex:[["fn main() {\n    let mut s = String::from(\"a\");\n    let a = &mut s;\n    let b = &mut s;\n    a.push_str(\"x\");\n    println!(\"{}\", s);\n}\n", "rejected: <code>E0499</code>, <code>a</code> is used after <code>b</code> starts", "E0499"], ["fn main() {\n    let s = String::from(\"a\");\n    let r = &s;\n    let t = s;\n    println!(\"{}\", r);\n}\n", "rejected: <code>E0505</code>, <code>s</code> moves while <code>r</code> points at it", "E0505"], ["fn main() {\n    let mut x = 5;\n    let r = &x;\n    x = 6;\n    println!(\"{}\", r);\n}\n", "rejected: <code>E0506</code>, <code>x</code> changes while <code>r</code> points at it", "E0506"], ["fn main() {\n    let v = vec![String::from(\"a\")];\n    let s = v[0];\n    println!(\"{}\", v.len());\n}\n", "rejected: <code>E0507</code>, <code>v[0]</code> stays in the <code>Vec</code>", "E0507"], ["fn main() {\n    let r: &i32;\n    {\n        let x = 5;\n        r = &x;\n    }\n    println!(\"{}\", r);\n}\n", "rejected: <code>E0597</code>, <code>x</code> ends with its block", "E0597"], ["fn pick<'a>(x: &'a str, y: &str) -> &'a str {\n    y\n}\nfn main() {\n    println!(\"{}\", pick(\"a\", \"b\"));\n}\n", "rejected: <code>E0621</code>, <code>y</code> has no <code>'a</code>", "E0621"]]},
 {ch:12,gl:1,c:"E0261, E0107, E0392 and E0726: lifetime and generic names",what:"<code>E0261</code>: a lifetime name is used but never declared. <code>E0107</code>: a generic type has the wrong number of type arguments, such as <code>Tag</code> with none for <code>Tag&lt;T&gt;</code>. <code>E0392</code>: a type or lifetime name is declared on a <code>struct</code> but no field uses it. <code>E0726</code>: an <code>impl</code> leaves out the lifetime of the <code>struct</code> it is for.",
  ex:[["fn show(x: &'a str) {\n    println!(\"{}\", x);\n}\nfn main() {\n    show(\"tide\");\n}\n", "rejected: <code>E0261</code>, <code>'a</code> is not declared", "E0261"], ["struct Tag<T> {\n    n: T,\n}\nfn main() {\n    let t: Tag = Tag { n: 1 };\n    println!(\"{}\", t.n);\n}\n", "rejected: <code>E0107</code>, <code>Tag</code> needs its <code>T</code>", "E0107"], ["struct Tag<T> {\n    n: i32,\n}\nfn main() {\n    println!(\"tag\");\n}\n", "rejected: <code>E0392</code>, no field uses <code>T</code>", "E0392"], ["struct Note<'a> {\n    text: &'a str,\n}\nimpl Note {\n    fn len(&self) -> usize {\n        self.text.len()\n    }\n}\nfn main() {\n    let words = String::from(\"meet\");\n    let note = Note { text: &words };\n    println!(\"{}\", note.len());\n}\n", "rejected: <code>E0726</code>, write <code>impl&lt;'a&gt; Note&lt;'a&gt;</code>", "E0726"]]},
 {ch:12,gl:1,c:"E0004, E0005, E0170 and E0530: patterns",what:"<code>E0004</code>: a <code>match</code> leaves some values without an arm. <code>E0005</code>: a plain <code>let</code> has a pattern that can fail, like <code>Some(n)</code>. <code>E0170</code>: a bare name in a pattern is a new variable, not the variant you meant, so write <code>E::A</code>. <code>E0530</code>: a pattern name reuses the name of a variant that holds data, such as <code>Some</code>.",
  ex:[["fn main() {\n    let b = true;\n    match b {\n        true => println!(\"t\"),\n    }\n}\n", "rejected: <code>E0004</code>, <code>false</code> has no arm", "E0004"], ["fn main() {\n    let o = Some(5);\n    let Some(n) = o;\n    println!(\"{}\", n);\n}\n", "rejected: <code>E0005</code>, <code>None</code> would not fit", "E0005"], ["enum E {\n    A,\n    B,\n}\n\nfn main() {\n    let e = E::B;\n    let n = match e {\n        A => 1,\n        _ => 2,\n    };\n    println!(\"{}\", n);\n}\n", "rejected: <code>E0170</code>, <code>A</code> is a new variable", "E0170"], ["fn main() {\n    let o = Some(1);\n    match o {\n        Some => println!(\"a\"),\n        None => println!(\"b\"),\n    }\n}\n", "rejected: <code>E0530</code>, <code>Some</code> needs its part", "E0530"]]},
 {ch:12,gl:1,c:"E0046, E0407, E0053 and E0050: an impl that does not match its trait",what:"<code>E0046</code>: an <code>impl</code> leaves out a method the trait requires. <code>E0407</code>: an <code>impl</code> has a method the trait does not list. <code>E0053</code>: a method has other parameter or result types than the trait. <code>E0050</code>: a method has another number of parameters than the trait.",
  ex:[["trait Shape {\n    fn side(&self) -> u32;\n    fn tag(&self) -> u32;\n}\nstruct Sq(u32);\nimpl Shape for Sq {\n    fn side(&self) -> u32 {\n        self.0\n    }\n}\nfn main() {\n    println!(\"{} {}\", Sq(3).side(), Sq(3).tag());\n}\n", "rejected: <code>E0046</code>, <code>tag</code> is missing", "E0046"], ["trait Shape {\n    fn side(&self) -> u32;\n    fn tag(&self) -> u32 {\n        0\n    }\n}\nstruct Sq(u32);\nimpl Shape for Sq {\n    fn side(&self) -> u32 {\n        self.0\n    }\n    fn tog(&self) -> u32 {\n        9\n    }\n}\nfn main() {\n    println!(\"{} {}\", Sq(3).side(), Sq(3).tag());\n}\n", "rejected: <code>E0407</code>, <code>tog</code> is not in <code>Shape</code>", "E0407"], ["trait Shape {\n    fn side(&self) -> u32;\n}\nstruct Sq(u32);\nimpl Shape for Sq {\n    fn side(&self) -> i32 {\n        3\n    }\n}\nfn main() {\n    println!(\"{}\", Sq(3).side());\n}\n", "rejected: <code>E0053</code>, the trait says <code>u32</code>", "E0053"], ["trait Shape {\n    fn scale(&self, k: u32) -> u32;\n}\nstruct Sq(u32);\nimpl Shape for Sq {\n    fn scale(&self) -> u32 {\n        self.0\n    }\n}\nfn main() {\n    println!(\"ok\");\n}\n", "rejected: <code>E0050</code>, the trait says two parameters", "E0050"]]},
 {ch:12,gl:1,c:"E0404, E0405, E0119, E0449, E0184 and E0040: trait names and rules",what:"<code>E0404</code>: a name used as a trait is a <code>struct</code> or something else. <code>E0405</code>: no trait has that name. <code>E0119</code>: two <code>impl</code> blocks cover the same trait for the same type. <code>E0449</code>: <code>pub</code> is written on a trait method. <code>E0184</code>: a type with an <code>impl Drop</code> also derives <code>Copy</code>. <code>E0040</code>: <code>drop</code> is called as a method, so write <code>drop(x)</code>.",
  ex:[["struct A {}\nfn show<T: A>(_t: T) {}\nfn main() {}\n", "rejected: <code>E0404</code>, <code>A</code> is a <code>struct</code>", "E0404"], ["trait Cry {\n    fn sound(&self) -> String;\n}\nstruct Dog;\nstruct Cat;\nimpl Cri for Dog {\n    fn sound(&self) -> String {\n        String::from(\"woof\")\n    }\n}\n\nfn main() {\n    println!(\"declared\");\n}\n", "rejected: <code>E0405</code>, <code>Cri</code> is not a trait", "E0405"], ["struct A;\nstruct B;\nimpl From<A> for A {\n    fn from(a: A) -> A {\n        a\n    }\n}\nfn main() {\n    println!(\"ok\");\n}\n", "rejected: <code>E0119</code>, the standard library already has it", "E0119"], ["trait T {\n    pub fn f(&self) -> i32;\n}\nfn main() {}\n", "rejected: <code>E0449</code>, no <code>pub</code> in a trait", "E0449"], ["#[derive(Clone, Copy)]\nstruct D;\nimpl Drop for D {\n    fn drop(&mut self) {\n        println!(\"drop\");\n    }\n}\nfn main() {\n    let _d = D;\n    println!(\"end\");\n}\n", "rejected: <code>E0184</code>, <code>Copy</code> and <code>Drop</code> do not mix", "E0184"], ["struct Guard;\nimpl Drop for Guard {\n    fn drop(&mut self) {\n        println!(\"drop\");\n    }\n}\nfn main() {\n    let g = Guard;\n    g.drop();\n    println!(\"end\");\n}\n", "rejected: <code>E0040</code>, write <code>drop(g)</code>", "E0040"]]},
 {ch:12,gl:1,c:"E0277, E0369, E0599 and E0609: what a type can do",what:"<code>E0277</code>: a type lacks the trait a place needs, such as <code>{}</code> on a type with no <code>Display</code>. <code>E0369</code>: an operator such as <code>+</code> or <code>==</code> is used on a type that does not support it. <code>E0599</code>: a method is called that the type does not have, or has only when its parts qualify. <code>E0609</code>: a field is read that the type does not have.",
  ex:[["fn main() {\n    let o = Some(5);\n    println!(\"{}\", o);\n}\n", "rejected: <code>E0277</code>, an <code>Option</code> has no <code>Display</code>", "E0277"], ["fn first<T>(a: T, b: T) -> T {\n    a + b\n}\nfn main() {\n    println!(\"{}\", first(1, 2));\n}\n", "rejected: <code>E0369</code>, <code>T</code> has no <code>+</code>", "E0369"], ["struct K(i32);\n\nfn main() {\n    let v = vec![K(1)];\n    let w = v.clone();\n    println!(\"{}\", w.len());\n}\n", "rejected: <code>E0599</code>, <code>K</code> is not <code>Clone</code>", "E0599"], ["struct P {\n    n: i32,\n}\n\nfn main() {\n    let p = P { n: 1 };\n    println!(\"{}\", p.m);\n}\n", "rejected: <code>E0609</code>, <code>P</code> has no <code>m</code>", "E0609"]]},
 {ch:12,gl:1,c:"E0282, E0283, E0373 and E0525: closures Rust cannot place",what:"<code>E0282</code> and <code>E0283</code>: Rust cannot work out a type, for example a closure parameter used with a method before its type is known, or a <code>sum</code> or <code>collect</code> with no type to build. <code>E0373</code>: a returned closure borrows a variable that does not outlive it, so add <code>move</code>. <code>E0525</code>: a closure needs more than the bound allows, such as changing a capture where <code>Fn</code> is asked for.",
  ex:[["fn main() {\n    let f = |s| s.len();\n    println!(\"{}\", f(\"abc\"));\n}\n", "rejected: <code>E0282</code>, <code>s</code> needs a type", "E0282"], ["fn main() {\n    let v = vec![1, 2, 3];\n    let s = v.iter().sum();\n    println!(\"{}\", 1);\n}\n", "rejected: <code>E0283</code>, <code>sum</code> needs a type", "E0283"], ["fn adder(n: i32) -> impl Fn(i32) -> i32 {\n    |x| x + n\n}\nfn main() {\n    println!(\"{}\", adder(2)(3));\n}\n", "rejected: <code>E0373</code>, the closure borrows <code>n</code>", "E0373"], ["fn apply<F: Fn()>(f: F) {\n    f();\n}\nfn main() {\n    let mut n = 0;\n    let inc = || n += 1;\n    apply(inc);\n    println!(\"{}\", n);\n}\n", "rejected: <code>E0525</code>, the closure is <code>FnMut</code>", "E0525"]]},
 {ch:12,gl:1,c:"E0593, E0631, E0057 and E0618: calling and passing closures",what:"<code>E0593</code>: a closure takes another number of parameters than the function asks for. <code>E0631</code>: a closure parameter has another type than the function passes it. <code>E0057</code>: a closure is called with the wrong number of arguments. <code>E0618</code>: something that is not a function or closure is called.",
  ex:[["fn apply<F: Fn(i32) -> i32>(f: F) -> i32 {\n    f(1)\n}\nfn main() {\n    println!(\"{}\", apply(|a, b| a + b));\n}\n", "rejected: <code>E0593</code>, one parameter is wanted", "E0593"], ["fn apply<F: Fn(i32) -> i32>(f: F) -> i32 {\n    f(1)\n}\nfn main() {\n    println!(\"{}\", apply(|a: String| 1));\n}\n", "rejected: <code>E0631</code>, an <code>i32</code> is passed", "E0631"], ["fn main() {\n    let f = |x: i32| x + 1;\n    println!(\"{}\", f(1, 2));\n}\n", "rejected: <code>E0057</code>, one argument is wanted", "E0057"], ["fn main() {\n    let x = 5;\n    println!(\"{}\", x(1));\n}\n", "rejected: <code>E0618</code>, <code>x</code> is a number", "E0618"]]},
 {ch:12,gl:1,c:"E0600: negating an unsigned number",what:"<code>E0600</code>: a <code>-</code> sits in front of a number whose type has no negative values, such as <code>u8</code>, <code>u32</code> or <code>usize</code>. It also happens with a cast like <code>-1 as u8</code>, because the <code>-</code> still belongs to the <code>1</code>. Use a signed type like <code>i32</code> when the value can go below zero.",
  ex:[["fn main() {\n    let x: u8 = -1;\n    println!(\"{}\", x);\n}\n", "rejected: <code>u8</code> has no negative values", "E0600"], ["fn main() {\n    let x = -1 as u8;\n    println!(\"{}\", x);\n}\n", "rejected: the <code>-</code> applies to the <code>1</code>, which the cast makes a <code>u8</code>", "E0600"], ["fn main() {\n    let y: u32 = 5;\n    let z = -y;\n    println!(\"{}\", z);\n}\n", "rejected: <code>y</code> is unsigned", "E0600"]]},
 {ch:12,gl:1,c:"E0716: a temporary dropped while it is borrowed",what:"<code>E0716</code>: a value that no variable holds, like the result of <code>String::from(\"a\")</code> or <code>make()</code>, is dropped at the end of its statement, but a borrow of it is used after that. <code>let r = &amp;String::from(\"a\");</code> is fine, because <code>let</code> keeps the temporary as long as <code>r</code> lives. So is borrowing a constant, like <code>&amp;5</code> or the <code>&amp;[1, 2, 3]</code> of a <code>for</code> loop. Put the value in a variable first, then borrow the variable.",
  ex:[["fn main() {\n    let s = String::from(\"a\").as_str();\n    println!(\"{}\", s);\n}\n", "rejected: the <code>String</code> is dropped at the end of the <code>let</code>", "E0716"], ["fn id(s: &String) -> &String {\n    s\n}\n\nfn main() {\n    let s = id(&String::from(\"a\"));\n    println!(\"{}\", s);\n}\n", "rejected: the result of <code>id</code> borrows the temporary <code>String</code>", "E0716"], ["fn main() {\n    let n = 1;\n    let mut last = &0;\n    for x in &[n, 2, 3] {\n        last = x;\n    }\n    println!(\"{}\", last);\n}\n", "rejected: <code>last</code> keeps a borrow of the temporary array, which holds the variable <code>n</code>", "E0716"]]}
];
})();
